import {createRoundedCrescentWorld} from '../../src/terrain/rounded-crescent-globe.ts';
import {ROUNDED_CRESCENT_DEFAULTS} from '../../src/surfaces/rounded-crescent-globe.ts';
import {prepareSphericalSession} from '../../src/editor/prepare-spherical-session.ts';
import {SphereWebGLRenderer} from '../../src/rendering/spherical-webgl.ts';
import {sphericalFieldRaster} from '../../src/rendering/spherical-field-raster.ts';
import type {SphericalView} from '../../src/rendering/spherical-view.ts';
export async function roundedRenderProbe(){
 const size={width:1000,height:660},world=createRoundedCrescentWorld({terrainId:'probe',identity:{worldId:'probe-world',surfaceId:'exterior'},dimensions:ROUNDED_CRESCENT_DEFAULTS,detail:128}),t=world.terrain;
 for(const k of t.samples()){const p=t.directionAt(k);t.write(k,600*Math.sin(5*p[0]+4*p[1])+450*p[2]-100);}
 const prepared=await prepareSphericalSession(t,'probe',false,{yield:()=>new Promise(r=>setTimeout(r,0))}),field=prepared.cache.elevationField!,snapshot=field.snapshot(),gpu=document.createElement('canvas'),cpu=document.createElement('canvas');document.body.append(gpu,cpu);const renderer=new SphereWebGLRenderer(gpu,field,()=>{},true),results=[];
 try{for(const[pose,angle]of[['front',0],['oblique',.25]] as const){const c=Math.cos(angle),s=Math.sin(angle),view:SphericalView={mode:'globe',frame:{right:[c,0,-s],up:[0,1,0],forward:[s,0,c]},zoom:1,pan:{x:0,y:0},roundedGlobe:world.geometry};renderer.present(view,size);if(!renderer.available)throw Error(renderer.statistics.reason);const gl=gpu.getContext('webgl2')!,raw=new Uint8Array(size.width*size.height*4);gl.readPixels(0,0,size.width,size.height,gl.RGBA,gl.UNSIGNED_BYTE,raw);const gpuPng=gpu.toDataURL();const steps=sphericalFieldRaster(snapshot,view,size,'relief',size.width*size.height,undefined,undefined,size);let image=steps.next(),at=performance.now();while(!image.done){image=steps.next();if(performance.now()-at>6){await new Promise(r=>setTimeout(r,0));at=performance.now();}}const p=image.value,cpuPixels=p.pixels;cpu.width=p.columns;cpu.height=p.rows;cpu.getContext('2d')!.putImageData(new ImageData(cpuPixels as Uint8ClampedArray<ArrayBuffer>,p.columns,p.rows),0,0);let max=0,alphaMax=0,stable=0,missing=0;const missingPoints:number[][]=[],alphaPoints:number[][]=[];for(let y=3;y<size.height-3;y++)for(let x=3;x<size.width-3;x++){const offset=(y*size.width+x)*4,gpuOffset=((size.height-y-1)*size.width+x)*4,a=cpuPixels[offset+3]!,b=raw[gpuOffset+3]!;alphaMax=Math.max(alphaMax,Math.abs(a-b));if(a!==b&&alphaPoints.length<30)alphaPoints.push([x,y,a,b]);if(a===255&&b===255&&[-2,0,2].every(d=>[-2,0,2].every(e=>cpuPixels[((y+d)*size.width+x+e)*4+3]===255))){stable++;for(let k=0;k<3;k++)max=Math.max(max,Math.abs(cpuPixels[offset+k]!-raw[gpuOffset+k]!));}if(a===255&&b===0){missing++;if(missingPoints.length<20)missingPoints.push([x,y]);}}
 results.push({pose,max,alphaMax,stable,missing,missingPoints,alphaPoints,graphics:{...renderer.statistics},gpu:gpuPng,cpu:cpu.toDataURL()});}
 }finally{renderer.dispose();prepared.editor.disableBackground();prepared.editor.releaseDisplay();gpu.remove();cpu.remove();}return results;
}
